+/** Convert the deliberately small, inline subset of Markdown links supported by this rule. */
+function getMarkdownLinkAt(text: string, start: number): MarkdownLink | null {
+  const image = text[start] === '!';
+  const labelStart = start + (image ? 1 : 0);
+  if (text[labelStart] !== '[') return null;
+
+  let labelEnd = labelStart + 1;
+  let bracketDepth = 1;
+  for (; labelEnd < text.length; labelEnd++) {
+    if (text[labelEnd] === '\\\') {
+      labelEnd++;
+    } else if (text[labelEnd] === '[') {
+      bracketDepth++;
+    } else if (text[labelEnd] === ']' && --bracketDepth === 0) {
+      break;
+    }
+  }
+
+  if (bracketDepth !== 0 || text[labelEnd + 1] !== '(') return null;
+
+  let end = labelEnd + 2;
+  let parenDepth = 1;
+  for (; end < text.length; end++) {
+    if (text[end] === '\\\') {
+      end++;
+    } else if (text[end] === '(') {
+      parenDepth++;
+    } else if (text[end] === ')' && --parenDepth === 0) {
+      break;
+    }
+  }
+
+  if (parenDepth !== 0) return null;
+  const label = text.slice(labelStart + 1, labelEnd);
+  const destination = text.slice(labelEnd + 2, end);
+  if (label.includes('\
') || destination.includes('\
')) return null;
+
+  const target = parseMarkdownDestination(destination);
+  if (target === null) return null;
+
+  return {end: end + 1, image, label: unescapeMarkdown(label), target};
+}
+
+/** Returns null for a title or a destination outside the supported inline syntax. */
+function parseMarkdownDestination(destination: string): string | null {
+  const trimmed = destination.trim();
+  if (trimmed.startsWith('<')) {
+    let close = -1;
+    for (let i = 1; i < trimmed.length; i++) {
+      if (trimmed[i] === '\\\') i++;
+      else if (trimmed[i] === '>') {
+        close = i;
+        break;
+      }
+    }
+    if (close === -1 || trimmed.slice(close + 1).trim() !== '') return null;
+    return unescapeMarkdown(trimmed.slice(1, close));
+  }
+
+  // An unescaped space in a bare destination introduces a Markdown title.
+  for (let i = 0; i < trimmed.length; i++) {
+    if (trimmed[i] === '\\\') {
+      i++;
+    } else if (/\\s/.test(trimmed[i])) {
+      return null;
+    }
+  }
+  return unescapeMarkdown(trimmed);
+}
+
+function unescapeMarkdown(value: string): string {
+  return value.replace(/\\\\(.)/g, '$1');
