+function convertMarkdownLinks(text: string, images: boolean): string {
+  let result = '';
+  let cursor = 0;
+  while (cursor < text.length) {
+    const isCandidate = images ? text[cursor] === '!' : text[cursor] === '[' && text[cursor - 1] !== '!';
+    if (!isCandidate) {
+      result += text[cursor++];
+      continue;
+    }
